import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"The example env file matches what the code reads","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules/env-example-sync.md","filePath":"reference/rules/env-example-sync.md"}`),a={name:`reference/rules/env-example-sync.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="the-example-env-file-matches-what-the-code-reads" tabindex="-1">The example env file matches what the code reads <a class="header-anchor" href="#the-example-env-file-matches-what-the-code-reads" aria-label="Permalink to “The example env file matches what the code reads”">​</a></h1><p>Every variable the code reads should be documented, and every documented variable should be one the code reads.</p><h2 id="why-it-is-a-rule" tabindex="-1">Why it is a rule <a class="header-anchor" href="#why-it-is-a-rule" aria-label="Permalink to “Why it is a rule”">​</a></h2><p>The example file is the only description of what a deployment must supply, and nothing links it to the code, so it drifts in both directions. An undocumented variable is one a production deployment silently runs without. A documented variable nothing reads is one operators keep setting for no reason.</p><h2 id="what-is-expected" tabindex="-1">What is expected <a class="header-anchor" href="#what-is-expected" aria-label="Permalink to “What is expected”">​</a></h2><p>Add the variable with a comment describing what it does and its default. A live <code>NAME=value</code>, a commented <code># NAME=value</code>, or a name leading an aligned comment table all count as documented.</p><h2 id="what-counts-as-a-read" tabindex="-1">What counts as a read <a class="header-anchor" href="#what-counts-as-a-read" aria-label="Permalink to “What counts as a read”">​</a></h2><p>Direct property and index access on <code>process.env</code> and <code>import.meta.env</code>, <code>Deno.env.get(...)</code> and <code>Bun.env.*</code>, helper calls like <code>envNumber(&quot;NAME&quot;)</code>, and destructuring. <code>const { API_URL, PORT = &quot;3000&quot; } = process.env</code> counts each ALL_CAPS name it binds, renames included.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><p>Matching is textual, so a name assembled at runtime from a prefix is missed. Writing variable names out in full keeps this rule working. Variables consumed outside the scanned sources, by a compose file or a container entrypoint, belong in the <code>externallyConsumed</code> option.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};